import json,os,ssl,socket,subprocess,urllib.request,urllib.error,datetime,shutil
H="serveriptv.duckdns.org"; R="/srv/projects/jellyfin-server"
d={}
def cmd(k,argv):
 try:
  p=subprocess.run(argv,text=True,capture_output=True,timeout=7)
  d[k]={"ok":p.returncode==0,"output":p.stdout.strip()[:350]}
 except Exception as e:d[k]={"ok":False,"error":type(e).__name__}
cmd("jellyfin_service",["systemctl","is-active","jellyfin-pink.service"])
cmd("nginx_service",["systemctl","is-active","nginx"])
cmd("nginx_config",["sudo","-n","nginx","-t"])
cmd("tcp_port_8096",["ss","-lntH","sport = :8096"])
cmd("private_network",["systemctl","show","-P","PrivateNetwork","jellyfin-pink.service"])
d["socket_exists"]=os.path.exists(R+"/run/jellyfin.sock")
d["socket_is_socket"]=__import__("stat").S_ISSOCK(os.stat(R+"/run/jellyfin.sock").st_mode) if d["socket_exists"] else False
d["admin_secret_exists"]=os.path.isfile(R+"/secrets/admin-initial.json")
d["admin_secret_permissions"]=oct(os.stat(R+"/secrets/admin-initial.json").st_mode&0o777) if d["admin_secret_exists"] else None
d["media_dirs"]={q:os.path.exists(R+"/"+q) for q in ["media","movies","series","tv"]}
d["disk_free_gib"]=round(shutil.disk_usage("/srv/projects").free/2**30,2)
d["root_size_mib"]=round(sum(os.path.getsize(os.path.join(p,f)) for p,_,fs in os.walk(R) for f in fs if not os.path.islink(os.path.join(p,f)))/2**20,1)
try:
 ctx=ssl.create_default_context()
 with socket.create_connection((H,443),timeout=6) as sock:
  with ctx.wrap_socket(sock,server_hostname=H) as tls:
   c=tls.getpeercert()
   d["https_cert"]={"verified":True,"valid_until":c.get("notAfter"),"san_has_domain":("DNS",H) in c.get("subjectAltName",())}
 with urllib.request.urlopen("https://"+H+"/System/Info/Public",timeout=9) as resp:
  x=json.loads(resp.read(10000))
  d["https_api"]={"status":resp.status,"version":x.get("Version",x.get("version")),"wizard_complete":x.get("StartupWizardCompleted",x.get("startupWizardCompleted"))}
except Exception as e:d["https_check_error"]=type(e).__name__+":"+str(e)[:180]
for h in ["https://www.lowcost-europa.eu/","https://sevelora.eu/"]:
 try:
  with urllib.request.urlopen(urllib.request.Request(h,method="HEAD"),timeout=8) as resp:
   d[h]={"status":resp.status}
 except urllib.error.HTTPError as e:d[h]={"status":e.code}
 except Exception as e:d[h]={"error":type(e).__name__}
print(json.dumps(d,sort_keys=True))
